window.CA = {"date": "Wednesday, 08 July 2026", "updated": "2026-07-08 04:28", "updated_label": "08 Jul 2026, 04:28 IST", "items": [{"title": "US Strikes Iran After Tanker Attacks in Strait of Hormuz; Three Ships Hit in 24 Hours", "category": "ir", "category_name": "International Relations", "summary": "The United States launched military strikes on Iran following attacks on British tankers in the Strait of Hormuz, with three ships struck within 24 hours. Washington described the strikes as a response to Iran's 'violation of truce'. The Strait of Hormuz is a critical chokepoint through which approximately 20% of global oil trade passes, making the flare-up significant for global energy markets. India, which imports a substantial share of its crude oil from the Gulf region, faces direct economic exposure to any sustained conflict.", "exam_angle": "Strait of Hormuz is a critical maritime chokepoint relevant to GS Paper 2 (IR) and GS Paper 3 (Economy/Energy Security). US-Iran tensions, freedom of navigation, and India's energy import dependence are recurring UPSC themes.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Strait of Hormuz: ~20% of global oil trade passes through it", "US launched strikes on Iran citing 'violation of truce'", "Three ships struck within 24 hours in the strait", "India imports a major share of crude from Gulf region — energy security implication"], "source": "The Hindu / Times of India", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "Indonesia to Purchase BrahMos Missiles; PM Modi Addresses Indonesian Parliament", "category": "defence", "category_name": "Defence & Security", "summary": "Indonesia has agreed to purchase BrahMos supersonic cruise missiles from India, deepening defence ties between the two nations. PM Narendra Modi addressed the Indonesian Parliament (DPR) during his state visit to Jakarta, calling Indonesia a 'natural space partner' and offering satellite launch capabilities. Modi also invoked the 'next 25 years' as crucial for India-Indonesia partnership and reiterated India's dialogue-and-diplomacy stance in the context of global tensions. India also signed a pact with Indonesia for cooperation in minerals and technology of the steel supply chain.", "exam_angle": "BrahMos export signals India's emergence as a defence exporter — directly relevant to GS Paper 3 (Defence/Internal Security) and GS Paper 2 (IR/India's Neighbourhood & Beyond). Indonesia is part of ASEAN, central to India's Act East Policy.", "gs_paper": "GS Paper 3 (Defence)", "key_facts": ["BrahMos: India-Russia joint venture supersonic cruise missile", "Indonesia becomes a BrahMos buyer — supports India's defence export goals", "PM Modi addressed Indonesian Parliament (DPR) during state visit to Jakarta", "India-Indonesia pact signed on minerals and steel supply chain technology"], "source": "Reuters / News18", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "PM Modi Addresses Indonesian Parliament: UNSC Reforms, Palestine Policy, Space Partnership", "category": "ir", "category_name": "International Relations", "summary": "Prime Minister Narendra Modi, during his address to the Indonesian Parliament, called for inclusive development and reforms in the United Nations Security Council (UNSC). Modi reiterated India's long-standing support for a two-state solution on Palestine and called for an immediate ceasefire. He offered Indonesia satellite launch capabilities, describing Jakarta as India's 'natural space partner', and emphasised the deep bond between India, Indonesia, and the Indian Ocean region. India and Indonesia also signed a pact on minerals and steel supply chain cooperation.", "exam_angle": "India's UNSC reform demand, Act East Policy, and India-Indonesia civilisational ties are recurring GS Paper 2 themes. India's Palestine policy (two-state solution, UNGA votes) is frequently asked.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["India supports UNSC reforms — permanent membership demand", "India reiterates two-state solution for Palestine; calls for immediate ceasefire", "India offers Indonesia satellite launch capability — space diplomacy", "India-Indonesia partnership termed crucial for 'next 25 years'"], "source": "Times of India / The Hindu / News18", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "FDI Inflows to India Rose 44% to USD 39 Billion in 2025: UN Report", "category": "reports", "category_name": "Reports & Indices", "summary": "According to a United Nations report, Foreign Direct Investment (FDI) inflows into India increased by 44% to USD 39 billion in 2025, reflecting growing investor confidence in the Indian economy. This makes India one of the top FDI destinations globally. PM Modi, addressing the Indian diaspora in Jakarta, stated that 'India's economy is driving global growth' and highlighted India's mantra of 'Reform, Perform and Transform'. India also urged the US to reconsider a proposed 12.5% tariff under USTR's Section 301 'forced labour' probe.", "exam_angle": "FDI data from UN/UNCTAD reports is directly asked in GS Paper 3 (Economy). India's trade disputes with the US under USTR Section 301 connect to WTO, trade policy, and bilateral economic relations.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["India FDI inflows: USD 39 billion in 2025 — up 44% YoY (UN report)", "India urged US to withdraw proposed 12.5% tariff under USTR Section 301 'forced labour' probe", "PM Modi: 'India is driving global growth'; mantra: Reform, Perform, Transform", "Auto component industry pivoting to FTAs as US exports remain flat"], "source": "Moneycontrol / Times of India", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "E20 Petrol Rollout Faces Supreme Court Scrutiny; Government Defends Ethanol Blending", "category": "economy", "category_name": "Economy & Banking", "summary": "A litigant before the Supreme Court alleged 'silent compulsion' in the E20 petrol rollout, claiming vehicle owners are being forced to use ethanol-blended fuel without adequate notification. Union Minister Hardeep Puri rejected claims of engine damage, stating that 'serviced vehicles are not facing difficulty'. India's ethanol blending programme targets 20% blending (E20) by 2025 under the National Biofuel Policy. The issue has political implications with reports suggesting it is impacting the BJP's electoral standing.", "exam_angle": "Ethanol blending is part of India's energy security and green fuel transition policy — GS Paper 3 (Economy/Environment). Supreme Court intervention on policy rollout connects to GS Paper 2 (Polity/Judiciary).", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["E20 = 20% ethanol blended petrol; India's target under National Biofuel Policy 2018", "Supreme Court hearing petition on 'silent compulsion' in E20 rollout", "Minister Hardeep Puri: 'Serviced vehicles not facing difficulty'", "E25 rethink also underway amid EV adoption challenges"], "source": "Times of India / The Hindu / Indian Express", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "Lawrence Bishnoi Gang Charged in US with Ordering Hardeep Singh Nijjar's 2023 Murder", "category": "ir", "category_name": "International Relations", "summary": "US prosecutors have charged members of the Lawrence Bishnoi gang with ordering the 2023 murder of Hardeep Singh Nijjar, a Canadian Sikh separatist, in British Columbia, Canada. The US indictment connects the Indian organised crime network to the assassination, which had previously triggered a major India-Canada diplomatic row. Separately, US prosecutors arrested 24 individuals in a major probe into India-based organised crime. An imprisoned Indian gang leader was specifically named in the charges.", "exam_angle": "India-Canada diplomatic tensions over Nijjar's killing, the Khalistan issue, and India's response to foreign interference are central to GS Paper 2 (IR). The US indictment internationalises the issue further.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Hardeep Singh Nijjar murdered in June 2023 in Surrey, British Columbia, Canada", "Lawrence Bishnoi gang named in US federal indictment", "US arrested 24 individuals in probe into India-based organised crime", "Issue triggered India-Canada diplomatic standoff in 2023"], "source": "Indian Express / Reuters / BBC", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "Trump Considers F-35 Sale to Turkey, Pledges to Lift Sanctions on Ankara", "category": "ir", "category_name": "International Relations", "summary": "US President Donald Trump, during his visit to Ankara, announced plans to lift sanctions on Turkey and said he would 'consider' selling F-35 stealth fighter jets to Türkiye. Israel's PM Benjamin Netanyahu publicly opposed the potential F-35 sale to Turkey. Turkey was originally removed from the F-35 programme in 2019 after it purchased Russia's S-400 air defence system, triggering US sanctions under CAATSA (Countering America's Adversaries Through Sanctions Act). The development has significant implications for NATO cohesion and West Asia geopolitics.", "exam_angle": "CAATSA is directly relevant as India also procured Russian S-400 systems and received a waiver — frequently asked in GS Paper 2 (IR). NATO solidarity, US-Turkey-Israel dynamics are important IR themes.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Turkey removed from F-35 programme in 2019 after S-400 purchase from Russia", "US sanctions on Turkey under CAATSA (Countering America's Adversaries Through Sanctions Act)", "Trump pledges to lift sanctions on Türkiye and consider F-35 sale", "India also procured S-400 from Russia and received CAATSA waiver"], "source": "Hindustan Times / Al Jazeera", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "Wayanad on Red Alert as Landslide Kills 4, Leaves 6 Missing at Tunnel Site", "category": "environment", "category_name": "Environment & Ecology", "summary": "Wayanad district in Kerala has been placed on red alert after a landslide at a tunnel construction site killed at least 4 people and left 6 missing. Mumbai received a brief respite after two days of heavy rain, while orange alerts were issued for several Maharashtra districts. The incidents are part of the active 2026 Southwest Monsoon season, which has caused widespread flooding and landslides across India's western coast. AI-based early warning systems helped Maharashtra authorities prepare for cloudburst-like rains in Nashik.", "exam_angle": "Landslide-prone zones, monsoon disasters, and disaster management are recurring themes in GS Paper 1 (Geography) and GS Paper 3 (Disaster Management). AI use in disaster early warning is a GS Paper 3 Sci-Tech angle.", "gs_paper": "GS Paper 1 (Geography)", "key_facts": ["Wayanad (Kerala) on red alert; 4 dead, 6 missing at tunnel construction site landslide", "Wayanad suffered major landslide disaster in July 2024 as well — recurring vulnerability", "AI-based early warning system used in Maharashtra's Nashik for cloudburst prediction", "India Meteorological Department issues colour-coded alerts: Green, Yellow, Orange, Red"], "source": "The Hindu / NDTV", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "TribeX Digital Platform for Tribal Arts and Culture Launched by Union Tribal Affairs Ministry", "category": "schemes", "category_name": "Govt Schemes & Policies", "summary": "Union Tribal Affairs Minister Jual Oram launched TribeX, a digital learning platform dedicated to tribal arts, culture, and traditional knowledge. The platform aims to preserve and promote India's rich tribal heritage by providing a digital repository and learning resource accessible to tribal communities and researchers. The launch aligns with India's broader push for digital inclusion of marginalised communities and the preservation of intangible cultural heritage.", "exam_angle": "Government schemes for tribal welfare and digital inclusion are important for GS Paper 2 (Governance/Social Justice). Preservation of intangible cultural heritage connects to GS Paper 1 (Culture).", "gs_paper": "GS Paper 2 (Governance)", "key_facts": ["Platform name: TribeX", "Launched by: Union Tribal Affairs Minister Jual Oram", "Focus: Digital learning for tribal arts, culture, and traditional knowledge", "Ministry: Ministry of Tribal Affairs"], "source": "PIB", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "DeepSeek's In-House Chip Development Rattles US Tech Stocks; Nasdaq Falls", "category": "scitech", "category_name": "Science & Technology", "summary": "Chinese AI startup DeepSeek announced plans to develop in-house AI chips, sending shockwaves through global semiconductor markets. US chip stocks including Nvidia, Intel, AMD, Micron, and Sandisk fell by up to 14%. The Nasdaq index was set to open lower as investor confidence in US AI chip dominance wavered. DeepSeek had earlier made global headlines in early 2025 when its low-cost AI model challenged US AI supremacy, raising questions about export control effectiveness.", "exam_angle": "AI chip competition between the US and China, semiconductor export controls, and India's semiconductor mission are key GS Paper 3 (Sci-Tech/Economy) themes. DeepSeek's emergence is a critical geopolitical technology story.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["DeepSeek (China) announced in-house AI chip development", "Nvidia, Intel, AMD fell up to 14% on the news", "US has imposed semiconductor export controls on China (CHIPS Act, BIS rules)", "India has its own semiconductor mission — India Semiconductor Mission (ISM)"], "source": "NDTV Profit", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "Bengaluru Startup's Surveillance Satellite Knocked Out by Solar Storm", "category": "scitech", "category_name": "Science & Technology", "summary": "A surveillance satellite operated by a Bengaluru-based startup was knocked out by a solar storm (geomagnetic disturbance), the company confirmed. The startup announced it is working on a comeback, highlighting the vulnerability of Low Earth Orbit (LEO) satellites to space weather events. Solar storms, caused by coronal mass ejections (CMEs) from the Sun, can damage satellite electronics and disrupt communications, GPS, and power grids. The incident underscores the importance of space weather monitoring for India's growing private space sector.", "exam_angle": "India's private space sector (IN-SPACe framework), solar storms and their effects, and LEO satellite vulnerability are important GS Paper 3 (Sci-Tech/Space) topics.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["Solar storm (coronal mass ejection/CME) knocked out a Bengaluru startup's surveillance satellite", "Geomagnetic storms can disrupt satellites, GPS, power grids, and HF radio", "India's private space sector regulated under IN-SPACe (Indian National Space Promotion and Authorisation Centre)", "Solar Cycle 25 (current cycle) has been more active than predicted"], "source": "NDTV", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "Government Directs EV Manufacturers to Strengthen Cybersecurity and Audit Battery Systems", "category": "scitech", "category_name": "Science & Technology", "summary": "The Indian government has directed electric vehicle (EV) manufacturers to tighten cybersecurity protocols and conduct mandatory audits of battery management systems. The directive comes amid growing concerns about data security in connected vehicles and the safety of lithium-ion battery packs after several fire incidents. India's EV sector has been growing rapidly under the FAME scheme and PM E-Bus Sewa programme, making regulatory oversight increasingly important.", "exam_angle": "EV policy, battery safety, and cybersecurity in connected vehicles are relevant to GS Paper 3 (Sci-Tech/Economy). FAME scheme and India's EV transition are standard topics.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["Govt directive to EV makers: tighten cybersecurity and audit battery management systems", "Connected EVs are potential cybersecurity vulnerabilities", "India's EV policy: FAME II scheme (Faster Adoption and Manufacturing of Electric Vehicles)", "Battery fires in EVs have been a recurring safety concern in India since 2022"], "source": "The New Indian Express", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "Ram Temple Board Overhauled After SIT Report on Donation Theft; Security Lapses Confirmed", "category": "culture", "category_name": "Art & Culture", "summary": "The Shri Ram Janmabhoomi Teertha Kshetra Trust overhauled its board following an SIT (Special Investigation Team) report that confirmed theft of cash donations and serious security protocol failures at the Ram Temple in Ayodhya. The SIT found that staff hired on a trust functionary's recommendations had stolen donations; six accused were identified. The Trust treasurer confirmed that valuable articles donated to the temple are safe and that over 30 kg of gold-like items are in the Trust's possession. The BBC reported the development as India's 'landmark Ram temple' undergoing significant reform.", "exam_angle": "The Ram Temple (consecrated January 2024) is a major cultural and constitutional landmark — connects to Article 25-28 (religious freedom), property rights of religious trusts, and governance of religious institutions.", "gs_paper": "GS Paper 1 (Culture)", "key_facts": ["Trust: Shri Ram Janmabhoomi Teertha Kshetra Trust, Ayodhya", "SIT report confirmed theft of donations and security protocol failures", "Trust board overhauled after the report", "Ram Temple consecrated on 22 January 2024 (Pran Pratishtha ceremony)"], "source": "BBC / NDTV / The Hindu", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "India-Indonesia Ink Pact on Minerals and Steel Supply Chain Technology", "category": "ir", "category_name": "International Relations", "summary": "India and Indonesia signed an agreement for cooperation in minerals and technology related to the steel supply chain during PM Modi's state visit to Jakarta. Indonesia is one of the world's largest producers of nickel, a critical mineral used in EV batteries and stainless steel, making the pact strategically important for India's energy transition and industrial goals. The agreement complements the BrahMos missile deal and broader defence-economic partnership announced during the visit.", "exam_angle": "Critical minerals diplomacy is a key GS Paper 3 (Economy) and GS Paper 2 (IR) theme. Indonesia's nickel reserves and India's need for critical minerals for EV batteries and green technology are important facts.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["India-Indonesia pact: cooperation in minerals and steel supply chain technology", "Indonesia: world's largest nickel producer — critical for EV batteries", "India's Critical Minerals Mission aims to secure supply of 30 critical minerals", "Agreement signed during PM Modi's state visit to Jakarta, July 2026"], "source": "Moneycontrol", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "PM Modi to Visit Australia After Indonesia; Human Rights Groups Plan Protests", "category": "ir", "category_name": "International Relations", "summary": "Following his state visit to Indonesia, PM Narendra Modi is set to visit Australia, where he is expected to receive a large diaspora welcome. However, human rights organisations plan protests over India's record on civil liberties and press freedom. India-Australia relations have deepened significantly since the Comprehensive Strategic Partnership signed in 2020, with defence, trade, and Quad cooperation as key pillars. The visit comes ahead of potential finalisation of the India-Australia Free Trade Agreement (ECTA) upgradation.", "exam_angle": "India-Australia bilateral relations, the Quad grouping, and India's diaspora diplomacy are standard GS Paper 2 (IR) topics. ECTA (Economic Cooperation and Trade Agreement) is a key trade policy fact.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["India-Australia: Comprehensive Strategic Partnership (2020)", "Both are Quad members (India, US, Australia, Japan)", "India-Australia ECTA (Interim FTA) signed April 2022", "Modi visit: diaspora outreach and strategic bilateral agenda"], "source": "The Guardian", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "Mumbai High Court: City Flooding 'Our Own Creation'; Cautions Against Blaming Civic Body", "category": "polity", "category_name": "Polity & Governance", "summary": "The Bombay High Court observed that Mumbai's recurring flooding is largely 'our own creation', cautioning petitioners against solely blaming the Brihanmumbai Municipal Corporation (BMC). The Court's remarks came amid heavy monsoon-related flooding in the city, with waterlogging affecting large parts of Mumbai. The observation highlights judicial concern over unplanned urbanisation, encroachment of natural drainage systems, and inadequate urban planning as root causes of flood vulnerability in India's financial capital.", "exam_angle": "Urban flooding, judicial activism on urban governance, and the role of municipal bodies connect to GS Paper 2 (Polity/Governance) and GS Paper 1 (Geography/Disaster Management).", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Bombay High Court: Mumbai flooding is 'our own creation' — not solely BMC's fault", "BMC (Brihanmumbai Municipal Corporation): India's richest municipal body", "Urban flooding linked to encroachment of Mithi River, Aarey, Mangroves", "74th Constitutional Amendment: Urban Local Bodies' responsibilities include urban planning"], "source": "NDTV", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "India–Indonesia Defence Deal: BrahMos and Astra Missiles to Be Supplied to Indonesia", "category": "defence", "category_name": "Defence & Security", "summary": "India is set to supply BrahMos supersonic cruise missiles and Astra air-to-air missiles to Indonesia, confirmed by an Indian government official during PM Modi's state visit to Jakarta. This marks a significant expansion of India's defence exports under its 'Make in India' and defence export push. The deal is part of a broader strategic partnership being formalised between the two countries. Indonesia becomes one of the key Southeast Asian nations to acquire the BrahMos system, which is jointly developed by India and Russia.", "exam_angle": "Relevant to GS Paper 2 (IR/Defence) — India's defence export ambitions, BrahMos as a strategic product, and deepening ties with ASEAN nations under Act East Policy.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Missiles: BrahMos (supersonic cruise) and Astra (air-to-air)", "BrahMos is a joint venture between India (DRDO/BrahMos Aerospace) and Russia", "Indonesia is an ASEAN nation; deal part of India's Act East Policy", "Announced during PM Modi's state visit to Jakarta (July 2026)"], "source": "Reuters / The Hindu", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "PM Modi Visits Indonesia: IIM Campus, UPI, AI, Critical Minerals and EVM Cooperation Announced", "category": "ir", "category_name": "International Relations", "summary": "PM Narendra Modi visited Jakarta, Indonesia, heralding what he called a 'golden chapter' in India–Indonesia relations. Key announcements included setting up an IIM Bangalore campus in Indonesia, extending UPI payment infrastructure, cooperation on artificial intelligence and critical minerals, and an MoU on election management including export of customised Electronic Voting Machines (EVMs). PM Modi also received Indonesia's highest civilian honour, the 'Bintang Adipurna'. PM Modi highlighted the next 25 years as crucial for the bilateral partnership and the Indian Ocean region.", "exam_angle": "Tests knowledge of India's bilateral diplomacy, Act East Policy, defence/tech exports, and India's soft power through institutions like IIMs. The EVM export MoU is significant for polity questions.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Award received: 'Bintang Adipurna' — Indonesia's highest state honour", "IIM Bangalore to set up campus in Indonesia", "MoU on election management and export of customised EVMs signed", "Cooperation areas: UPI, AI, critical minerals, satellite launch capability, defence"], "source": "The Times of India / News18 / NDTV", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "PM Modi Offers Indonesia Satellite Launch Capability; Deepens Space Partnership", "category": "scitech", "category_name": "Science & Technology", "summary": "During PM Modi's visit to Jakarta, India offered Indonesia satellite launch capability as part of deepening the bilateral space partnership. This aligns with ISRO's expanding commercial launch services under NewSpace India Limited (NSIL). The offer reflects India's growing role as a provider of space services to developing and partner nations in the Indo-Pacific region. Space cooperation was among multiple high-tech areas announced during the summit.", "exam_angle": "Links to ISRO's commercial arm NSIL, India's space diplomacy, and the broader theme of India as a space-faring nation offering services to allies.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["India offered satellite launch capability to Indonesia", "ISRO's commercial arm: NewSpace India Limited (NSIL)", "Part of India–Indonesia summit outcomes, July 2026", "Relevant to India's Act East Policy and space diplomacy"], "source": "News18", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "India Urges US to Reconsider Proposed 12.5% Tariff Under USTR Section 301 'Forced Labour' Probe", "category": "economy", "category_name": "Economy & Banking", "summary": "India has formally urged the United States to reconsider a proposed 12.5% tariff on Indian goods being examined under a Section 301 investigation by the US Trade Representative (USTR) related to 'forced labour' allegations. This is a significant trade friction point between the two countries as India seeks to protect its export competitiveness in the US market. Section 301 of the US Trade Act allows the USTR to investigate and impose tariffs on countries engaging in unfair trade practices. India's pushback comes amid broader India-US trade negotiations.", "exam_angle": "Tests knowledge of US trade law mechanisms (Section 301), India-US trade relations, and WTO/tariff dispute frameworks relevant to GS Paper 3 (Economy/IR).", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["Tariff proposed: 12.5% on certain Indian goods", "Investigation authority: USTR under Section 301 of US Trade Act", "Basis of probe: 'Forced labour' allegations", "India has formally requested reconsideration of the tariff"], "source": "The Times of India", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "2008 Ahmedabad Serial Blasts Case: Gujarat High Court Upholds Death Penalty for 38 Convicts", "category": "polity", "category_name": "Polity & Governance", "summary": "The Gujarat High Court upheld the death penalty for 38 convicts in the 2008 Ahmedabad serial blasts case, which involved a series of bomb explosions across the city that killed over 56 people and injured hundreds. The government described the verdict as a 'historic victory'. The case involved one of the largest terrorist attacks in India and the trial court had earlier awarded the death sentence to 38 and life imprisonment to others. The High Court confirmation is a necessary step before the matter can go to the Supreme Court.", "exam_angle": "Relevant to criminal law, capital punishment jurisprudence, and constitutional provisions on the right to life (Article 21). Also tests knowledge of India's counter-terrorism legal framework.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Incident: 2008 Ahmedabad serial bomb blasts (56+ killed)", "Court: Gujarat High Court upheld death penalty", "Number of convicts on death row confirmed: 38", "Mandatory confirmation of death sentences by High Court under CrPC before Supreme Court appeal"], "source": "The Hindu", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "E20 Petrol Row: Supreme Court Takes Up Petition; Concerns Over Damage to E10 Vehicles", "category": "environment", "category_name": "Environment & Ecology", "summary": "A report and a Supreme Court petition have raised concerns that E20 petrol (containing 20% ethanol blended with petrol) may damage rubber fuel system components in older vehicles designed for E10 (10% ethanol blend). A litigant before the Supreme Court alleged 'silent compulsion' in the E20 rollout. India is pursuing its ethanol blending programme — achieving 20% blending by 2025–26 — as part of its energy security and climate commitments. Petroleum Minister Hardeep Puri defended the programme, saying car manufacturers are comfortable with the transition.", "exam_angle": "Connects to India's National Biofuel Policy, ethanol blending targets, energy security, and the intersection of environmental policy with consumer rights.", "gs_paper": "GS Paper 3 (Environment)", "key_facts": ["E20 = 20% ethanol blended petrol; E10 = 10% ethanol blend", "India's target: 20% ethanol blending by 2025–26 under National Biofuel Policy 2018", "Concern: E20 may damage rubber parts in E10-compatible vehicles", "Matter raised before the Supreme Court of India"], "source": "Moneycontrol / The Hindu", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "Wayanad Landslide: IMD Red Alert, 5 Dead; Kerala Ministers Term It 'Man-Made Disaster'", "category": "environment", "category_name": "Environment & Ecology", "summary": "A landslide struck Wayanad district in Kerala following heavy rainfall, killing at least 5 people and prompting a red alert from the India Meteorological Department (IMD). Two Kerala ministers termed the disaster 'man-made', raising questions about construction activity and deforestation in the ecologically sensitive Western Ghats. Wayanad was the site of a catastrophic landslide in July 2024 as well, making it a region of recurring disaster vulnerability. Simultaneously, the IMD issued red alerts for Delhi and an orange alert for Mumbai as the monsoon intensified across India.", "exam_angle": "Relevant to disaster management, Western Ghats ecology, Gadgil and Kasturirangan Committee recommendations on ecologically sensitive zones, and IMD's alert system.", "gs_paper": "GS Paper 3 (Environment)", "key_facts": ["Location: Wayanad, Kerala — ecologically sensitive part of Western Ghats", "Deaths: At least 5 in the latest landslide", "IMD alert levels: Red (extreme), Orange (very heavy), Yellow (heavy rainfall) — colour-coded system", "Kerala ministers attributed the disaster to human activity ('man-made')"], "source": "The Hindu / NDTV", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "Strait of Hormuz Tanker Attacks: Three Commercial Ships Hit, Oil Prices Rise", "category": "ir", "category_name": "International Relations", "summary": "The United Kingdom Maritime Trade Operations (UKMTO) reported that three commercial tankers were hit by unidentified projectiles in the Strait of Hormuz, with no casualties reported. Oil prices rose on reports of the attack, which was attributed to Iranian-linked activity by media reports. The Strait of Hormuz is one of the world's most critical oil chokepoints, through which roughly 20% of global oil trade passes. The attacks are part of ongoing escalation in the West Asia/Middle East region.", "exam_angle": "Strait of Hormuz is a critical chokepoint for global energy security and directly impacts India's oil import costs. Relevant to GS Paper 2 (IR) and GS Paper 3 (Economy — energy security).", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Location: Strait of Hormuz — between Iran and Oman", "~20% of global oil trade passes through the Strait of Hormuz", "Reporting authority: UKMTO (UK Maritime Trade Operations)", "Three tankers hit; oil prices rose on news of attacks"], "source": "The Hindu", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "Macron Visits Syria: Blast Near Damascus Hotel During French Presidential Visit", "category": "ir", "category_name": "International Relations", "summary": "French President Emmanuel Macron made a state visit to Damascus, Syria — a significant diplomatic visit marking engagement with Syria's new post-Assad government. During the visit, a blast was reported near his hotel, though Macron was unharmed. The visit signalled Western re-engagement with Syria following the fall of Bashar al-Assad's government. France's diplomatic outreach to Syria is part of broader international efforts to stabilise the country and address the refugee and humanitarian crisis.", "exam_angle": "Relevant to GS Paper 2 (IR) — geopolitics of West Asia, France's foreign policy, and Syria's post-conflict political transition.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["French President Macron visited Damascus, Syria", "Blast reported near his hotel during the visit; Macron was unharmed", "Significance: Western diplomatic re-engagement with post-Assad Syria", "Syria's Assad government fell in late 2024 after rebel offensive"], "source": "NDTV", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "UNICEF: Over 300 Children Killed or Wounded in Sudan War in Six Months", "category": "ir", "category_name": "International Relations", "summary": "UNICEF reported that over 300 children have been killed or wounded in Sudan's ongoing civil war over a period of six months, highlighting the severe humanitarian toll of the conflict between the Sudanese Armed Forces (SAF) and the Rapid Support Forces (RSF). The Sudan conflict, which began in April 2023, has created one of the world's largest displacement crises. UNICEF's report underscores the violation of international humanitarian law and the targeting of civilian infrastructure in the war.", "exam_angle": "Relevant to GS Paper 2 (IR) — international organisations (UNICEF), humanitarian law, and Africa-related current affairs that frequently appear in UPSC Prelims.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["300+ children killed or wounded in Sudan conflict over 6 months: UNICEF", "Sudan conflict: SAF vs RSF (Rapid Support Forces), began April 2023", "One of the world's largest displacement/humanitarian crises", "UNICEF is a UN agency focused on children's welfare (HQ: New York)"], "source": "NDTV", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "Trump Considers Selling F-35 Fighter Jets to Turkey", "category": "defence", "category_name": "Defence & Security", "summary": "US President Donald Trump stated that the United States would consider selling F-35 stealth fighter jets to Turkey. Turkey was originally part of the F-35 programme but was removed in 2019 after it purchased Russia's S-400 air defence system, triggering US sanctions under CAATSA (Countering America's Adversaries Through Sanctions Act). Trump's statement signals a possible shift in US policy and a potential easing of tensions with Turkey, a NATO ally. The development is significant for NATO cohesion and US arms export policy.", "exam_angle": "Connects to CAATSA (relevant because India also purchased S-400 from Russia), NATO dynamics, and US arms export policy — all frequent UPSC IR themes.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["F-35 is a 5th-generation stealth multirole fighter (Lockheed Martin)", "Turkey was expelled from F-35 programme in 2019 after S-400 purchase from Russia", "CAATSA (Countering America's Adversaries Through Sanctions Act) was the sanctions basis", "India also purchased S-400 from Russia and faced CAATSA waiver pressure"], "source": "NDTV", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "Ukraine Strikes 8 Russian 'Shadow Fleet' Tankers Delivering Fuel to Crimea", "category": "ir", "category_name": "International Relations", "summary": "Ukraine conducted strikes on eight Russian 'shadow fleet' tankers that were delivering fuel to Crimea, which Russia annexed in 2014. The 'shadow fleet' refers to vessels used by Russia to circumvent Western oil sanctions imposed after the 2022 invasion of Ukraine. Targeting of these tankers represents Ukraine's strategy to disrupt Russian fuel supply lines, especially to occupied territories. The development has implications for global shipping insurance and maritime security.", "exam_angle": "Relevant to the Russia-Ukraine conflict, Western sanctions architecture, the concept of 'shadow fleets', and energy security — all important for GS Paper 2 IR and GS Paper 3 Economy.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["'Shadow fleet': vessels used to evade Western oil sanctions on Russia", "Crimea was annexed by Russia in 2014; internationally recognised as Ukrainian territory", "Eight tankers struck by Ukraine in this operation", "Western sanctions cap Russian oil at $60/barrel under G7 Price Cap mechanism"], "source": "NDTV", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "TribeX Digital Learning Platform for Tribal Arts and Culture Launched by Union Tribal Affairs Minister", "category": "schemes", "category_name": "Govt Schemes & Policies", "summary": "Union Minister for Tribal Affairs Jual Oram launched 'TribeX', a digital learning platform dedicated to tribal arts, culture, and traditional knowledge. The platform is designed to preserve, promote, and disseminate India's rich tribal heritage in a digital format, making it accessible to tribal communities and the wider public. The launch aligns with the Ministry of Tribal Affairs' mandate to protect tribal identities and livelihoods under constitutional provisions (Articles 15, 16, 46, and the Fifth and Sixth Schedules).", "exam_angle": "Relevant to GS Paper 2 (Schemes/Welfare) — government initiatives for tribal welfare, digital empowerment, and constitutional safeguards for Scheduled Tribes.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Platform name: TribeX", "Launched by: Union Minister Jual Oram, Ministry of Tribal Affairs", "Purpose: Digital learning for tribal arts, culture, and traditional knowledge", "Relevant constitutional provisions: Articles 46, Fifth Schedule, Sixth Schedule (NE India)"], "source": "PIB", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "Taj Mahal–Tejo Mahalaya Petition: Allahabad High Court Issues Notice to Centre", "category": "culture", "category_name": "Art & Culture", "summary": "The Allahabad High Court issued a notice to the Central Government on a petition claiming that the Taj Mahal was built on a pre-existing Hindu temple site called 'Tejo Mahalaya'. The petition seeks a court-directed investigation into the historical claims. The Taj Mahal, built by Mughal Emperor Shah Jahan in the 17th century in Agra, is a UNESCO World Heritage Site and one of India's most iconic monuments. Similar petitions in the past have been dismissed by courts.", "exam_angle": "Relevant to heritage/culture questions, Places of Worship (Special Provisions) Act 1991, and constitutional provisions on religious sites — a recurring issue in UPSC current affairs.", "gs_paper": "GS Paper 1 (Culture)", "key_facts": ["Monument: Taj Mahal, Agra — UNESCO World Heritage Site (designated 1983)", "Built by: Mughal Emperor Shah Jahan (17th century) in memory of Mumtaz Mahal", "Petition claims: Taj Mahal built over 'Tejo Mahalaya' Hindu temple site", "Court: Allahabad High Court issued notice to Centre"], "source": "NDTV", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "ZEE5 Removes 'Satluj' (Punjab 95) After Government Cites IT Rules and Security Concerns", "category": "polity", "category_name": "Polity & Governance", "summary": "OTT platform ZEE5 removed the film 'Satluj' (based on the Diljit Dosanjh-produced 'Punjab 95', depicting the human rights situation during the 1984–95 Punjab militancy period) after the government cited security concerns and the IT Rules 2021 as grounds for the takedown. The film had previously been held up by the Central Board of Film Certification (CBFC). SGPC and Shiromani Akali Dal condemned the removal. The case raises questions about OTT regulation, freedom of expression, and government powers under the IT (Intermediary Guidelines and Digital Media Ethics Code) Rules 2021.", "exam_angle": "Directly relevant to GS Paper 2 (Polity) — OTT regulation under IT Rules 2021, CBFC's powers, freedom of speech (Article 19(1)(a)), and reasonable restrictions.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Film: 'Satluj' (Punjab 95) — depicts 1984–95 Punjab militancy and human rights issues", "Platform: ZEE5 removed the film citing government direction", "Legal basis cited: IT (Intermediary Guidelines and Digital Media Ethics Code) Rules 2021", "Regulatory body: CBFC (Central Board of Film Certification) had earlier withheld certification"], "source": "The Indian Express", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "Pakistan Issues 'War' Threat Over Indus Waters Amid Suspended Treaty", "category": "ir", "category_name": "International Relations", "summary": "Pakistan issued statements threatening war with India over Indus Waters, amid the monsoon season when river flows are high and following India's suspension of the Indus Waters Treaty (IWT) after the Pahalgam terrorist attack in April 2025. India suspended the 1960 Indus Waters Treaty — brokered by the World Bank — as a retaliatory measure. The IWT governs the sharing of six rivers of the Indus system between India and Pakistan, with the western rivers (Indus, Jhelum, Chenab) allocated to Pakistan and eastern rivers (Ravi, Beas, Sutlej) to India.", "exam_angle": "Critical for GS Paper 2 (IR) — Indus Waters Treaty, India–Pakistan relations, water diplomacy, and World Bank's role as a mediator/guarantor.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Indus Waters Treaty (IWT) signed in 1960 — brokered by World Bank", "Western rivers (Indus, Jhelum, Chenab) allocated to Pakistan; Eastern (Ravi, Beas, Sutlej) to India", "India suspended IWT after Pahalgam terror attack (April 2025)", "Pakistan threatened war over Indian actions on Indus water flows"], "source": "NDTV", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "India's Semiconductor (Chip) Manufacturing Push Faces Execution Challenges", "category": "economy", "category_name": "Economy & Banking", "summary": "An analysis highlights that India's semiconductor manufacturing ambitions face the biggest challenge not in policy design but in execution — including lack of specialised talent, supply chain gaps, water and power requirements, and delays in facility construction. India has approved semiconductor projects under the India Semiconductor Mission (ISM), including facilities by Tata Electronics (in Dholera, Gujarat) and Micron Technology (ATMP facility in Sanand, Gujarat). The global chip race is intensifying with the US CHIPS Act and EU Chips Act offering competing incentives.", "exam_angle": "Directly relevant to GS Paper 3 (Economy/Sci-Tech) — India Semiconductor Mission, Atmanirbhar Bharat in electronics, and critical technology supply chains.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["India Semiconductor Mission (ISM) launched under MeitY with Rs 76,000 crore incentive package", "Approved projects: Tata Electronics (Dholera, Gujarat) and Micron Technology ATMP (Sanand, Gujarat)", "Key challenge highlighted: Execution — talent, supply chain, infrastructure", "Global context: US CHIPS Act ($52 bn) and EU Chips Act competing for semiconductor investment"], "source": "The Times of India", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "India-UK Free Trade Agreement Set for July 15 Rollout; Industry Welcomes Pact", "category": "ir", "category_name": "International Relations", "summary": "The India-UK Free Trade Agreement (FTA) is scheduled to come into effect on July 15, 2026, sparking significant industry optimism. The pact covers goods, services, and investment, and is expected to boost bilateral trade substantially. It is one of the most comprehensive trade deals India has signed in recent years, covering sectors including pharmaceuticals, textiles, professional services, and digital trade.", "exam_angle": "India's bilateral trade agreements are a recurring GS Paper 2 (IR) and GS Paper 3 (Economy) topic; aspirants should know key provisions, sectors covered, and strategic significance of the India-UK FTA.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["India-UK FTA rollout date: July 15, 2026", "Covers goods, services, investment, and digital trade", "One of India's most comprehensive bilateral trade deals", "Sectors benefiting: pharmaceuticals, textiles, professional services"], "source": "India Today", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "India Lifts Gas Supply Curbs Imposed During Strait of Hormuz Disruption as LNG Supply Resumes", "category": "economy", "category_name": "Economy & Banking", "summary": "India lifted emergency gas supply restrictions that were imposed during a period of disruption to shipping through the Strait of Hormuz. The government confirmed that 15 India-bound ships carrying urea, DAP (diammonium phosphate), and sulphur had successfully crossed the Hormuz Strait. The Hormuz Strait is critical to India's energy security, as a significant share of India's crude oil and LNG imports transit through it. The lifting of curbs signals normalisation of supply chains.", "exam_angle": "The Strait of Hormuz is strategically vital for India's energy imports; this event connects to India's energy security, import dependency, and West Asia geopolitics — all frequent exam themes.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["15 India-bound ships carrying urea, DAP, sulphur crossed Hormuz", "India lifted gas supply curbs imposed during Hormuz disruption", "LNG and fertiliser supply chains now normalised", "Strait of Hormuz: critical chokepoint for India's oil and gas imports"], "source": "The Quint / The Times of India", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "India and Russia Set $50 Billion Bilateral Investment Target by 2030", "category": "ir", "category_name": "International Relations", "summary": "India and Russia have agreed to set a bilateral investment target of $50 billion by 2030, deepening economic engagement between the two countries. This comes amid continued strategic partnership even as Russia faces Western sanctions over the Ukraine conflict. The investment push covers sectors such as energy, defence, fertilisers, and infrastructure. India-Russia trade has surged in recent years, particularly in crude oil imports.", "exam_angle": "India-Russia economic ties, especially amid Western sanctions and India's strategic autonomy doctrine, are highly relevant for GS Paper 2 (IR) and GS Paper 3 (Economy).", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["India-Russia bilateral investment target: $50 billion by 2030", "Sectors: energy, defence, fertilisers, infrastructure", "India-Russia trade has expanded significantly due to crude oil imports post-2022", "Russia remains a key defence supplier and strategic partner for India"], "source": "The Economic Times", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "EAM Jaishankar on 4-Nation Diplomatic Tour; Meets Qatar PM on Energy and West Asia", "category": "ir", "category_name": "International Relations", "summary": "External Affairs Minister S. Jaishankar undertook a 4-nation diplomatic tour, which included a meeting with the Prime Minister of Qatar to review bilateral energy ties, trade relations, and the situation in West Asia. Qatar is one of India's largest suppliers of LNG and is home to a large Indian diaspora. The visit comes amid heightened tensions in the region following the death of Iranian Supreme Leader Ali Khamenei.", "exam_angle": "India's West Asia diplomacy, energy security (LNG from Qatar), and diaspora engagement are key GS Paper 2 (IR) topics; EAM Jaishankar's tours frequently appear in current affairs.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["EAM Jaishankar undertook a 4-nation diplomatic tour", "Met Qatar PM to review energy, trade, and West Asia situation", "Qatar is a major LNG supplier to India", "Visit coincides with regional tensions post-Khamenei death"], "source": "India Today", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "Netanyahu Cites India's Support After JD Vance Calls US 'Only Ally' of Israel", "category": "ir", "category_name": "International Relations", "summary": "Israeli Prime Minister Benjamin Netanyahu pushed back against US Vice President JD Vance's claim that the US was Israel's 'only ally,' explicitly citing India and its 1.4 billion people as friends of Israel. This public statement highlights the growing perception of India-Israel strategic closeness even as India has maintained a formal stance supporting the two-state solution. The remark drew significant attention to the nature of India's foreign policy balancing act.", "exam_angle": "India-Israel relations, India's West Asia policy, and India's strategic autonomy (maintaining ties with both Israel and Arab/Palestinian sides) are key GS Paper 2 (IR) themes.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Netanyahu cited India ('1.4 billion Indians') as supporters of Israel", "JD Vance had called the US Israel's 'only ally'", "India officially supports the two-state solution for Palestine", "India-Israel defence and technology ties have deepened since 2017"], "source": "NDTV / News18", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "PM Modi's Indonesia Visit to Focus on UPI, Defence, and Digital Public Infrastructure Partnership", "category": "ir", "category_name": "International Relations", "summary": "Prime Minister Narendra Modi's upcoming visit to Indonesia is set to focus on expanding UPI (Unified Payments Interface) adoption, defence cooperation, and digital public infrastructure (DPI) partnerships. Indonesia is one of the largest economies in Southeast Asia and an important partner in ASEAN. India has been actively promoting its DPI stack — including UPI, Aadhaar, and DigiLocker — as a global model for digital governance.", "exam_angle": "India's Act East Policy, UPI's global expansion, and DPI diplomacy are central to GS Paper 2 (IR) and GS Paper 3 (Sci-Tech/Economy); Indonesia is a key ASEAN partner.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Modi's Indonesia visit agenda: UPI expansion, defence, Digital Public Infrastructure", "Indonesia is a key ASEAN and G20 partner for India", "India's DPI stack (UPI, Aadhaar, DigiLocker) being promoted globally", "UPI now operational in several countries through bilateral MoUs"], "source": "NDTV Profit", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "Trump to Meet Zelensky and Syrian President at NATO Summit in Turkey", "category": "ir", "category_name": "International Relations", "summary": "US President Donald Trump is scheduled to meet Ukrainian President Zelensky and Syria's new President at the upcoming NATO Summit to be held in Turkey. Trump also held a 'businesslike' phone call with Russian President Putin, offering again to facilitate a ceasefire in Ukraine. The NATO summit in Turkey is significant as it brings together key actors in the ongoing conflicts in both Ukraine and West Asia.", "exam_angle": "NATO's evolving role, US-Russia-Ukraine conflict dynamics, and Turkey's strategic positioning within NATO are important GS Paper 2 (IR) themes for Prelims and Mains.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["NATO Summit venue: Turkey", "Trump to meet Zelensky and Syrian President at the summit", "Trump-Putin call described as 'businesslike'; US offered mediation on Ukraine", "Russia claimed it captured Kostiantynivka town; Ukraine disputed the claim"], "source": "NDTV", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "Iran Seeks Tighter Control Over Strait of Hormuz Following Khamenei's Death", "category": "ir", "category_name": "International Relations", "summary": "Following the death of Iranian Supreme Leader Ali Khamenei, Iran has signalled intentions to tighten its control over the Strait of Hormuz, a critical global oil and gas chokepoint. The US reportedly pressured countries to reduce participation at Khamenei's funeral, with at least 13 nations withdrawing or reducing their delegations. Khamenei's son Mojtaba, widely seen as a potential successor, notably skipped the funeral. The post-Khamenei succession dynamics could significantly affect regional stability.", "exam_angle": "The Strait of Hormuz is the world's most critical oil chokepoint; Iran's leadership transition has major implications for India's energy security, West Asia stability, and global oil markets.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Ali Khamenei was Iran's Supreme Leader; died recently", "Mojtaba Khamenei is considered the likely successor but skipped the funeral", "Strait of Hormuz: ~20% of global oil trade passes through it", "US pressured at least 13 nations to reduce participation at Khamenei's funeral"], "source": "NDTV / The Guardian", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "India's Ethanol Blending (E20) Programme Faces Pushback from Motorists Over Mileage Concerns", "category": "schemes", "category_name": "Govt Schemes & Policies", "summary": "India's ethanol blending programme — which mandates E20 fuel (20% ethanol blended with petrol) — is facing public resistance from motorists citing reduced fuel efficiency (mileage loss) and engine compatibility concerns. Oil companies and the auto industry have defended the safety and viability of E20, while the government maintains the programme is essential for energy security and reducing carbon emissions. The E20 target is part of India's National Biofuel Policy 2018.", "exam_angle": "India's biofuel/ethanol blending programme is directly linked to energy security, agriculture (sugarcane/maize as feedstock), and climate commitments — a cross-cutting GS Paper 3 topic.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["E20: petrol blended with 20% ethanol; mandated under National Biofuel Policy 2018", "India's ethanol blending target: 20% by 2025-26", "Concerns: reduced mileage, engine compatibility for older vehicles", "Ethanol feedstock: sugarcane, maize, food grain surplus"], "source": "Bloomberg / The Indian Express", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "Centre Cracks Down on Instagram Over Child Sexual Abuse Content; Orders Immediate Ad Suspension", "category": "polity", "category_name": "Polity & Governance", "summary": "The Central Government has issued a stern notice to Instagram, ordering it to immediately stop running advertisements and demanding a response over the platform's failure to curb child sexual abuse material (CSAM) content. The Ministry of Electronics and Information Technology (MeitY) is the nodal authority for regulating digital intermediaries in India under the IT Act 2000 and IT (Intermediary Guidelines and Digital Media Ethics Code) Rules 2021. This action reflects increasing government scrutiny of Big Tech platforms.", "exam_angle": "Digital regulation of social media intermediaries under IT Rules 2021, CSAM as a legal issue, and MeitY's regulatory role are highly relevant for GS Paper 2 (Polity/Governance) and GS Paper 3 (Sci-Tech).", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Government ordered Instagram to stop ads over CSAM content", "Nodal authority: MeitY (Ministry of Electronics and IT)", "Governing law: IT Act 2000 + IT (Intermediary Guidelines) Rules 2021", "Intermediaries must act on CSAM within 24 hours under IT Rules 2021"], "source": "The Times of India", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "India's Passport Ranking Slips; Remains Outside Top 100 on Global Passport Index", "category": "reports", "category_name": "Reports & Indices", "summary": "India's passport ranking has fallen further, remaining outside the top 100 on the latest global passport power index. The Henley Passport Index ranks passports by the number of visa-free or visa-on-arrival destinations accessible. India's passport provides access to a limited number of countries without prior visa, reflecting the relatively restricted global mobility of Indian passport holders compared to top-ranked nations.", "exam_angle": "Passport indices and India's global standing on such indices are frequently tested in Prelims; connects to bilateral visa agreements, diplomatic relations, and soft power.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["India's passport ranking: outside top 100 (Henley Passport Index 2026)", "Henley Passport Index ranks by number of visa-free/on-arrival destinations", "Top-ranked passports (2026): typically Singapore, Japan, Germany, France", "India's passport grants visa-free access to approximately 58-62 countries"], "source": "The Times of India", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "Army Corners Two Lashkar-e-Taiba Terrorists in J&K's Shopian; Counter-Terror Operation Underway", "category": "defence", "category_name": "Defence & Security", "summary": "The Indian Army launched a counter-terrorism operation in the Shopian district of Jammu & Kashmir after surveillance cameras detected two local Lashkar-e-Taiba (LeT) militants in an orchard. The Army plugged escape routes and cordoned off the area. Operations in Shopian are part of ongoing counter-insurgency efforts in the Kashmir Valley, where LeT remains one of the most active proscribed terrorist organisations.", "exam_angle": "Counter-terror operations in J&K, Lashkar-e-Taiba's designation as a terrorist organisation, and India's security architecture in J&K are key defence and internal security topics for GS Paper 3.", "gs_paper": "GS Paper 3 (Defence)", "key_facts": ["Location: Shopian district, Jammu & Kashmir", "Group: Lashkar-e-Taiba (LeT) — UN-designated terrorist organisation", "Army used surveillance cameras to detect militants", "LeT is based in Pakistan; banned under UAPA in India"], "source": "The Times of India / NDTV", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "Indian Naval Ships Conclude Successful Visit to Singapore, Deepening Maritime Ties", "category": "defence", "category_name": "Defence & Security", "summary": "Indian Naval ships concluded a successful port visit to Singapore as part of ongoing efforts to strengthen maritime cooperation in the Indo-Pacific region. India and Singapore have robust defence ties, including regular bilateral naval exercises such as SIMBEX (Singapore-India Maritime Bilateral Exercise). Singapore is a key partner in India's Act East Policy and plays an important role in the strategic Malacca Strait region.", "exam_angle": "India's maritime diplomacy, Act East Policy, Indo-Pacific strategy, and India-Singapore defence relations are recurring GS Paper 2 (IR) and GS Paper 3 (Defence) themes.", "gs_paper": "GS Paper 3 (Defence)", "key_facts": ["Indian Naval ships completed a port visit to Singapore", "India-Singapore bilateral naval exercise: SIMBEX (held annually)", "Singapore is a key partner in India's Act East Policy", "Malacca Strait: strategic chokepoint near Singapore critical for India's trade"], "source": "PIB", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "NFDC-NFAI's 4K Restoration of 'Oka Oorie Katha' Makes World Premiere at 60th Karlovy Vary International Film Festival", "category": "culture", "category_name": "Art & Culture", "summary": "The National Film Development Corporation (NFDC) and National Film Archive of India (NFAI) jointly restored the 1977 Telugu classic 'Oka Oorie Katha' (directed by Mrinal Sen) in 4K and premiered it at the 60th Karlovy Vary International Film Festival in the Czech Republic. This is part of India's film heritage preservation initiative. NFAI, under MIB, is responsible for preserving and restoring India's cinematic heritage.", "exam_angle": "Film heritage conservation by NFDC/NFAI and India's cultural diplomacy through film festivals are relevant for GS Paper 1 (Culture) and GS Paper 2 (Governance/Soft Power).", "gs_paper": "GS Paper 1 (Culture)", "key_facts": ["Film: 'Oka Oorie Katha' (1977 Telugu film, dir. Mrinal Sen)", "Restored in 4K by NFDC and NFAI jointly", "World Premiere: 60th Karlovy Vary International Film Festival, Czech Republic", "NFAI (National Film Archive of India) is under Ministry of Information & Broadcasting"], "source": "PIB", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "Meghalaya's South Garo Hills Records Zero Maternal Deaths for Eight Consecutive Months", "category": "schemes", "category_name": "Govt Schemes & Policies", "summary": "South Garo Hills district in Meghalaya has achieved zero maternal deaths for eight consecutive months, a remarkable public health milestone for a region that had historically recorded high maternal mortality. This achievement is attributed to improved institutional deliveries, better ANM (Auxiliary Nurse Midwife) coverage, and effective implementation of centrally sponsored schemes such as Janani Suraksha Yojana (JSY) and the POSHAN Abhiyaan. Meghalaya's MMR had been one of the higher ones among northeastern states.", "exam_angle": "Maternal Mortality Rate (MMR) reduction, Janani Suraksha Yojana, and healthcare delivery in northeastern states are key GS Paper 2 (Governance/Social Justice) topics.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["South Garo Hills, Meghalaya: zero maternal deaths for 8 consecutive months", "Key schemes driving this: Janani Suraksha Yojana (JSY), POSHAN Abhiyaan", "India's target MMR: below 70 per lakh live births (SDG target: below 70 by 2030)", "India's national MMR has declined significantly over the past decade"], "source": "NDTV", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "India Needs Second Home for Asiatic Lions: Conservation Experts", "category": "environment", "category_name": "Environment & Ecology", "summary": "Conservation experts and reports have reiterated the urgency of establishing a second home for the Asiatic lion (Panthera leo persica), currently found exclusively in the Gir National Park and Wildlife Sanctuary in Gujarat. The Supreme Court had earlier directed the central government to relocate some lions to Kuno-Palpur National Park in Madhya Pradesh. The single-population vulnerability makes Asiatic lions susceptible to extinction from disease outbreaks or natural disasters.", "exam_angle": "Asiatic lion conservation, Project Lion, Gir National Park, the Supreme Court's Kuno-Palpur relocation order, and biodiversity protection connect to GS Paper 3 (Environment) and GS Paper 2 (Polity/Judiciary).", "gs_paper": "GS Paper 3 (Environment)", "key_facts": ["Asiatic Lion (Panthera leo persica): found only in Gir, Gujarat — IUCN: Endangered", "Supreme Court directed relocation of some lions to Kuno-Palpur NP, Madhya Pradesh", "Current Asiatic lion population: approximately 674 (2020 census)", "Project Lion launched in 2020 to protect and increase lion population"], "source": "The Hindu", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "India's Top IT Firms Face Muted Q1 Results as AI Spending Fails to Translate into Revenue Growth", "category": "economy", "category_name": "Economy & Banking", "summary": "A report projects that India's top IT companies — including TCS, Infosys, Wipro, and HCL Technologies — are set for subdued Q1 FY27 results despite heavy AI-related spending by global clients. The disconnect between AI investment and actual IT services revenue growth reflects a transition period where AI tools are being implemented but have not yet generated large-scale outsourcing contracts. TCS Q1 results are among the key events watched in the week ahead.", "exam_angle": "India's IT sector performance, the impact of AI on outsourcing, and India's services exports are relevant for GS Paper 3 (Economy); IT sector is a major contributor to India's GDP and foreign exchange earnings.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["India's IT sector: contributes ~7.5% of GDP and ~50% of service exports", "Top IT firms: TCS, Infosys, Wipro, HCL Technologies, Tech Mahindra", "Muted Q1 FY27 growth attributed to slower discretionary spending globally", "AI adoption is disrupting traditional IT outsourcing models"], "source": "The Times of India", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "Drone Delivery Ecosystem Expands in India Amid Regulatory Push for Last-Mile Solutions", "category": "scitech", "category_name": "Science & Technology", "summary": "India's drone delivery sector is witnessing rapid expansion, with multiple startups and logistics companies testing drone-based last-mile delivery in healthcare (medicines, vaccines), e-commerce, and agriculture. The Drone Rules 2021 and the PLI scheme for drones have provided regulatory clarity and financial incentives. The government's 'Drone Shakti' initiative under the Union Budget 2022-23 aims to make India a global drone hub.", "exam_angle": "Drone policy (Drone Rules 2021, PLI for drones, Drone Shakti), DGCA's regulatory role, and drone applications in healthcare and logistics are frequently tested in GS Paper 3 (Sci-Tech).", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["Drone Rules 2021 provide regulatory framework for civilian drone operations in India", "PLI Scheme for Drones: approved with Rs 120 crore outlay", "'Drone Shakti' initiative announced in Union Budget 2022-23", "DGCA is the nodal authority for drone regulation in India"], "source": "NDTV", "day": "2026-07-06", "day_label": "06 Jul"}], "categories": [{"id": "polity", "name": "Polity & Governance"}, {"id": "economy", "name": "Economy & Banking"}, {"id": "ir", "name": "International Relations"}, {"id": "environment", "name": "Environment & Ecology"}, {"id": "scitech", "name": "Science & Technology"}, {"id": "schemes", "name": "Govt Schemes & Policies"}, {"id": "defence", "name": "Defence & Security"}, {"id": "reports", "name": "Reports & Indices"}, {"id": "culture", "name": "Art & Culture"}]};